const response = $input.first().json;
if (response.meta?.hasMore) throw new Error('Danh mục vượt 500 tài liệu; cần bật phân trang trước khi đồng bộ');
const rows = Array.isArray(response.data) ? response.data : [];
return rows.flatMap((row) => {
  const folderId = String(row.driveFolderId ?? '').trim();
  if (!folderId) return [];
  return [{ json: {
    documentId: row.id,
    title: row.title,
    decisionNumber: row.decisionNumber ?? '',
    driveFolderId: folderId,
  } }];
});

const sources = $('Chuẩn bị thư mục').all();
const responses = $input.all();
const clean = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
return responses.map((response, index) => {
  const source = sources[index]?.json ?? {};
  const error = response.json.error ?? response.json.message;
  if (error) {
    const message = typeof error === 'string' ? error : JSON.stringify(error);
    const denied = /403|forbidden|permission|quyen/i.test(message);
    return { json: { documentId: source.documentId, driveFolderId: source.driveFolderId, syncStatus: denied ? 'ACCESS_DENIED' : 'ERROR', syncError: message.slice(0, 1000) } };
  }
  const files = Array.isArray(response.json.files) ? response.json.files : [];
  const pdfs = files.filter((file) => file.mimeType === 'application/pdf' && !file.trashed);
  if (pdfs.length === 0) return { json: { documentId: source.documentId, driveFolderId: source.driveFolderId, syncStatus: 'MISSING', syncError: 'Thư mục không có file PDF' } };
  let selected = pdfs.length === 1 ? pdfs[0] : null;
  if (!selected) {
    const decisionToken = String(source.decisionNumber ?? '').match(/\d{3,}/)?.[0] ?? '';
    const byDecision = decisionToken ? pdfs.filter((file) => clean(file.name).includes(decisionToken)) : [];
    if (byDecision.length === 1) selected = byDecision[0];
  }
  if (!selected) {
    const official = pdfs.filter((file) => /(^|[ _.-])(chinh[_ -]?thuc|hieu[_ -]?luc)([ _.-]|$)/i.test(clean(file.name)));
    if (official.length === 1) selected = official[0];
  }
  if (!selected) return { json: { documentId: source.documentId, driveFolderId: source.driveFolderId, syncStatus: 'NEEDS_REVIEW', syncError: `Có ${pdfs.length} file PDF, chưa xác định chắc chắn file chính` } };
  return { json: {
    documentId: source.documentId,
    driveFolderId: source.driveFolderId,
    driveFileId: selected.id,
    driveFileName: selected.name,
    driveMimeType: selected.mimeType,
    driveModifiedTime: selected.modifiedTime,
    driveChecksum: selected.md5Checksum ?? null,
    syncStatus: 'SYNCED',
    syncError: null,
  } };
});

const rows = $input.all().map((item) => item.json);
const batches = [];
for (let index = 0; index < rows.length; index += 100) batches.push({ json: { documents: rows.slice(index, index + 100) } });
return batches;
